import { build } from 'esbuild';
import { mkdir, readdir, copyFile } from 'node:fs/promises';
await mkdir('dist', {recursive:true});
const names = await readdir('src/web');
await build({entryPoints:names.filter(n=>n.endsWith('.js')).map(n=>'src/web/'+n),outdir:'dist',bundle:true,format:'esm',minify:true,sourcemap:true});
for (const name of names.filter(n=>/\.(html|css)$/.test(n))) await copyFile('src/web/'+name,'dist/'+name);

import { createApp } from './server.js';
const port = Number(process.env.PORT || 3000);
const server = createApp().listen(port, () => console.log('Shop listening on ' + server.address().port));
for (const signal of ['SIGINT', 'SIGTERM']) process.on(signal, () => server.close());

import express from 'express';
export function createApp({ dataDir = new URL('../data/', import.meta.url).pathname } = {}) {
  const app = express();
  app.use(express.json());
  app.get('/health', (req, res) => res.json({ status: 'ok' }));
  app.use((req, res) => res.status(404).json({ error: { code: 'NOT_FOUND', message: 'Route not found' } }));
  app.use((error, req, res, next) => res.status(error.status || 400).json({ error: { code: error.code || 'INVALID_INPUT', message: error.message } }));
  return app;
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { fixture } from './helpers.js';
test('health and unknown routes have structured responses', async t => {
  const { request } = await fixture(t);
  assert.deepEqual(await request('/health'), { status:200, body:{status:'ok'} });
  assert.equal((await request('/missing')).body.error.code, 'NOT_FOUND');
});

import { mkdtemp, cp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { createApp } from '../src/server.js';
export async function fixture(t, options = {}) {
  const dir = await mkdtemp(join(tmpdir(), 'shop-test-'));
  await cp(new URL('../data/', import.meta.url), dir, { recursive: true });
  const server = createApp({ dataDir: dir, ...options }).listen(0, '127.0.0.1');
  await new Promise((resolve, reject) => { server.once('listening', resolve); server.once('error', reject); });
  t.after(async () => { await new Promise(resolve => server.close(resolve)); await rm(dir, { recursive:true, force:true }); });
  const base = 'http://127.0.0.1:' + server.address().port;
  async function request(path, method = 'GET', body, headers = {}) {
    const response = await fetch(base + path, { method, headers: { 'content-type':'application/json', ...headers }, body: body === undefined ? undefined : JSON.stringify(body) });
    return { status:response.status, body: await response.json() };
  }
  return { request, dir, base };
}
